(function () {
  const D = window.MIAILHE_LOGOS_CHATEAUX;
  document.querySelectorAll('[data-logo-chateau]').forEach(el => {
    const v = (D[el.dataset.logoChateau] || {})[el.dataset.forme || 'logotype'] || (D[el.dataset.logoChateau] || {}).logo;
    if (!v || el.querySelector('svg')) return;
    const [, , w, h] = v.viewBox.split(' ').map(Number);
    el.style.setProperty('--ratio', (w / h).toFixed(4));
    el.style.setProperty('--retrait', v.retrait);
    el.style.setProperty('--encre', v.encre);
    el.insertAdjacentHTML('beforeend', `<svg viewBox="${v.viewBox}" style="aspect-ratio:${w} / ${h}" aria-hidden="true" focusable="false"><path fill="currentColor" d="${v.d}"/></svg>`);
  });
})();
